export interface BBox {
  x0: number;
  y0: number;
  x1: number;
  y1: number;
}

export interface PathPart {
  d: string;
  dx: number;
  dy: number;
  /** Path bounding box in SVG units, already offset by dx/dy. */
  bbox: BBox;
}

export interface Composition {
  frame: BBox;
  body: PathPart[];
  dot: PathPart[];
}

